<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class AccountSalaryController extends Controller {
 private function school(){ $u=auth()->user();abort_unless($u->status && $u->school_id,403);return $u->school_id; }
 private function payments(){return DB::table('account_salary_payments')->where('school_id',$this->school());}
 private function slips(){return DB::table('hr_payslips as p')->join('hr_payroll_runs as r','r.id','=','p.payroll_run_id')->join('users as u','u.id','=','p.user_id')->where('p.school_id',$this->school())->where('r.school_id',$this->school())->where('u.school_id',$this->school())->where('r.status','finalized')->select('p.*','u.name','r.finalized_at')->selectSub($this->payments()->whereColumn('payslip_id','p.id')->selectRaw('COALESCE(SUM(amount),0)'),'paid');}
 private function month(Request $r){$r->validate(['month'=>'nullable|date_format:Y-m']);return $r->month??now()->format('Y-m');}
 public function index(Request $r){$month=$this->month($r);$q=$this->slips()->where('p.pay_month',$month);$summary=DB::query()->fromSub(clone $q,'s')->selectRaw('COALESCE(SUM(net_salary),0) total, COALESCE(SUM(paid),0) paid, COALESCE(SUM(GREATEST(net_salary-paid,0)),0) due')->first();$rows=$q->orderBy('u.name')->paginate(20)->withQueryString();$history=$this->payments()->whereIn('payslip_id',$rows->pluck('id'))->orderByDesc('id')->get()->groupBy('payslip_id');return view('accounts.salary',compact('month','summary','rows','history'));}
 public function pay(Request $r,$id){$v=$r->validate(['amount'=>'required|numeric|decimal:0,2|min:0.01|max:9999999999.99','payment_date'=>'required|date_format:Y-m-d|before_or_equal:today','payment_mode'=>'required|in:cash,bank_transfer,upi,cheque,other','reference'=>'required_unless:payment_mode,cash|nullable|string|max:255','request_key'=>'required|uuid']);DB::transaction(function()use($v,$id){$p=DB::table('hr_payslips')->where('school_id',$this->school())->where('id',$id)->lockForUpdate()->first();abort_unless($p,404);$run=DB::table('hr_payroll_runs')->where('school_id',$this->school())->where('id',$p->payroll_run_id)->where('status','finalized')->first();abort_unless($run,422,'Payroll must be finalized.');$old=$this->payments()->where('request_key',$v['request_key'])->first();if($old){abort_unless($old->payslip_id==$id && $old->amount==$v['amount'] && $old->payment_date==$v['payment_date'] && $old->payment_mode==$v['payment_mode'] && $old->reference==($v['reference']??null),422,'Payment request already used.');return;} $paid=$this->payments()->where('payslip_id',$id)->sum('amount');abort_unless(round($v['amount']*100)<=round($p->net_salary*100)-round($paid*100),422,'Amount exceeds outstanding salary.');abort_unless($v['payment_date']>=substr($run->finalized_at,0,10),422,'Payment cannot precede finalization.');DB::table('account_salary_payments')->insert($v+['school_id'=>$this->school(),'payslip_id'=>$id,'paid_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Salary payment recorded.');}
 public function voucher($id){$payment=$this->payments()->where('id',$id)->first();abort_unless($payment,404);$slip=$this->slips()->where('p.id',$payment->payslip_id)->first();abort_unless($slip,404);return view('accounts.salary-voucher',compact('payment','slip'));}
 public function export(Request $r){$month=$this->month($r);$rows=$this->slips()->where('p.pay_month',$month)->orderBy('u.name')->get();return response()->streamDownload(function()use($rows){$f=fopen('php://output','w');fputcsv($f,['Employee ID','Employee','Month','Net salary','Paid','Outstanding']);foreach($rows as $p){$name=preg_match('/^[\s=+@-]/u',$p->name)?"'".$p->name:$p->name;fputcsv($f,[$p->user_id,$name,$p->pay_month,$p->net_salary,$p->paid,max(0,$p->net_salary-$p->paid)]);}fclose($f);},'salary-register-'.$month.'.csv',['Content-Type'=>'text/csv']);}
}
